   437  // ------------------------------------------------------------------------------------------------
   438  // Get a skin from a MDL7 file - more complex than all other subformats
   439  void MDLImporter::ParseSkinLump_3DGS_MDL7(
   440          const unsigned char *szCurrent,
   441          const unsigned char **szCurrentOut,
   442          aiMaterial *pcMatOut,
   443          unsigned int iType,
   444          unsigned int iWidth,
   445          unsigned int iHeight) {
   446      std::unique_ptr<aiTexture> pcNew;
   447
   448      // get the type of the skin
   449      unsigned int iMasked = (unsigned int)(iType & 0xF);
   450
   451      if (0x1 == iMasked) {
   452          // ***** REFERENCE TO ANOTHER SKIN INDEX *****
   453          int referrer = (int)iWidth;
   454          pcMatOut->AddProperty<int>(&referrer, 1, AI_MDL7_REFERRER_MATERIAL);
   455      } else if (0x6 == iMasked) {
   456          // ***** EMBEDDED DDS FILE *****
   457          if (1 != iHeight) {
   458              ASSIMP_LOG_WARN("Found a reference to an embedded DDS texture, "
   459                              "but texture height is not equal to 1, which is not supported by MED");
   460          }
   461
   462          pcNew.reset(new aiTexture());
   463          pcNew->mHeight = 0;
   464          pcNew->mWidth = iWidth;
   465
   466          // place a proper format hint
   467          pcNew->achFormatHint[0] = 'd';
   468          pcNew->achFormatHint[1] = 'd';
   469          pcNew->achFormatHint[2] = 's';
   470          pcNew->achFormatHint[3] = '\0';
   471
   472          pcNew->pcData = (aiTexel *)new unsigned char[pcNew->mWidth];
   473          memcpy(pcNew->pcData, szCurrent, pcNew->mWidth);
   474          szCurrent += iWidth;
   475      } else if (0x7 == iMasked) {
   476          // ***** REFERENCE TO EXTERNAL FILE *****
   477          if (1 != iHeight) {
   478              ASSIMP_LOG_WARN("Found a reference to an external texture, "
   479                              "but texture height is not equal to 1, which is not supported by MED");
   480          }
   481
   482          aiString szFile;
   483          const size_t iLen = strlen((const char *)szCurrent);
   484          size_t iLen2 = iLen + 1;
   485          iLen2 = iLen2 > MAXLEN ? MAXLEN : iLen2;
   486          memcpy(szFile.data, (const char *)szCurrent, iLen2);
   487          szFile.length = (ai_uint32)iLen;
   488
   489          szCurrent += iLen2;
   490
   491          // place this as diffuse texture
   492          pcMatOut->AddProperty(&szFile, AI_MATKEY_TEXTURE_DIFFUSE(0));
   493      } else if (iMasked || !iType || (iType && iWidth && iHeight)) {
   494          pcNew.reset(new aiTexture());
   495          if (!iHeight || !iWidth) {
   496              ASSIMP_LOG_WARN("Found embedded texture, but its width "
   497                              "an height are both 0. Is this a joke?");
   498
   499              // generate an empty chess pattern
   500              pcNew->mWidth = pcNew->mHeight = 8;
   501              pcNew->pcData = new aiTexel[64];
   502              for (unsigned int x = 0; x < 8; ++x) {
   503                  for (unsigned int y = 0; y < 8; ++y) {
   504                      const bool bSet = ((0 == x % 2 && 0 != y % 2) ||
   505                                         (0 != x % 2 && 0 == y % 2));
   506
   507                      aiTexel *pc = &pcNew->pcData[y * 8 + x];
   508                      pc->r = pc->b = pc->g = (bSet ? 0xFF : 0);
   509                      pc->a = 0xFF;
   510                  }
   511              }
   512          } else {
   513              // it is a standard color texture. Fill in width and height
   514              // and call the same function we used for loading MDL5 files
   515
   516              pcNew->mWidth = iWidth;
   517              pcNew->mHeight = iHeight;
   518
   519              unsigned int iSkip = 0;
   520              ParseTextureColorData(szCurrent, iMasked, &iSkip, pcNew.get());
   521
   522              // skip length of texture data
   523              szCurrent += iSkip;
   524          }
   525      }
