   106  // Returns whether the class can handle the format of the given file.
   107  bool MDLImporter::CanRead(const std::string &pFile, IOSystem *pIOHandler, bool checkSig) const {
   108      const std::string extension = GetExtension(pFile);
   109
   110      // if check for extension is not enough, check for the magic tokens
   111      if (extension == "mdl" || !extension.length() || checkSig) {
   112          uint32_t tokens[8];
   113          tokens[0] = AI_MDL_MAGIC_NUMBER_LE_HL2a;
   114          tokens[1] = AI_MDL_MAGIC_NUMBER_LE_HL2b;
   115          tokens[2] = AI_MDL_MAGIC_NUMBER_LE_GS7;
   116          tokens[3] = AI_MDL_MAGIC_NUMBER_LE_GS5b;
   117          tokens[4] = AI_MDL_MAGIC_NUMBER_LE_GS5a;
   118          tokens[5] = AI_MDL_MAGIC_NUMBER_LE_GS4;
   119          tokens[6] = AI_MDL_MAGIC_NUMBER_LE_GS3;
   120          tokens[7] = AI_MDL_MAGIC_NUMBER_LE;
   121          return CheckMagicToken(pIOHandler, pFile, tokens, 8, 0);
   122      }
   123      return false;
   124  }
