   304  // ------------------------------------------------------------------------------------------------
   305  // Validate a quake file header
   306  void MDLImporter::ValidateHeader_Quake1(const MDL::Header *pcHeader) {
   307      // some values may not be nullptr
   308      if (!pcHeader->num_frames)
   309          throw DeadlyImportError("[Quake 1 MDL] There are no frames in the file");
   310
   311      if (!pcHeader->num_verts)
   312          throw DeadlyImportError("[Quake 1 MDL] There are no vertices in the file");
   313
   314      if (!pcHeader->num_tris)
   315          throw DeadlyImportError("[Quake 1 MDL] There are no triangles in the file");
   316
   317      // check whether the maxima are exceeded ...however, this applies for Quake 1 MDLs only
   318      if (!this->iGSFileVersion) {
   319          if (pcHeader->num_verts > AI_MDL_MAX_VERTS)
   320              ASSIMP_LOG_WARN("Quake 1 MDL model has more than AI_MDL_MAX_VERTS vertices");
   321
   322          if (pcHeader->num_tris > AI_MDL_MAX_TRIANGLES)
   323              ASSIMP_LOG_WARN("Quake 1 MDL model has more than AI_MDL_MAX_TRIANGLES triangles");
   324
   325          if (pcHeader->num_frames > AI_MDL_MAX_FRAMES)
   326              ASSIMP_LOG_WARN("Quake 1 MDL model has more than AI_MDL_MAX_FRAMES frames");
   327
   328          // (this does not apply for 3DGS MDLs)
   329          if (!this->iGSFileVersion && pcHeader->version != AI_MDL_VERSION)
   330              ASSIMP_LOG_WARN("Quake 1 MDL model has an unknown version: AI_MDL_VERSION (=6) is "
   331                              "the expected file format version");
   332          if (pcHeader->num_skins && (!pcHeader->skinwidth || !pcHeader->skinheight))
   333              ASSIMP_LOG_WARN("Skin width or height are 0");
   334      }
   335  }
