   339  void FlipQuakeHeader(BE_NCONST MDL::Header *pcHeader) {
   340      AI_SWAP4(pcHeader->ident);
   341      AI_SWAP4(pcHeader->version);
   342      AI_SWAP4(pcHeader->boundingradius);
   343      AI_SWAP4(pcHeader->flags);
   344      AI_SWAP4(pcHeader->num_frames);
   345      AI_SWAP4(pcHeader->num_skins);
   346      AI_SWAP4(pcHeader->num_tris);
   347      AI_SWAP4(pcHeader->num_verts);
   348      for (unsigned int i = 0; i < 3; ++i) {
   349          AI_SWAP4(pcHeader->scale[i]);
   350          AI_SWAP4(pcHeader->translate[i]);
   351      }
   352      AI_SWAP4(pcHeader->size);
   353      AI_SWAP4(pcHeader->skinheight);
   354      AI_SWAP4(pcHeader->skinwidth);
   355      AI_SWAP4(pcHeader->synctype);
   356  }
