   528  // ------------------------------------------------------------------------------------------------
   529  // Setup material properties for Quake and older GameStudio files
   530  void MDLImporter::SetupMaterialProperties_3DGS_MDL5_Quake1() {
   531      const MDL::Header *const pcHeader = (const MDL::Header *)this->mBuffer;
   532
   533      // allocate ONE material
   534      pScene->mMaterials = new aiMaterial *[1];
   535      pScene->mMaterials[0] = new aiMaterial();
   536      pScene->mNumMaterials = 1;
   537
   538      // setup the material's properties
   539      const int iMode = (int)aiShadingMode_Gouraud;
   540      aiMaterial *const pcHelper = (aiMaterial *)pScene->mMaterials[0];
   541      pcHelper->AddProperty<int>(&iMode, 1, AI_MATKEY_SHADING_MODEL);
   542
   543      aiColor4D clr;
   544      if (0 != pcHeader->num_skins && pScene->mNumTextures) {
   545          // can we replace the texture with a single color?
   546          clr = this->ReplaceTextureWithColor(pScene->mTextures[0]);
   547          if (is_not_qnan(clr.r)) {
   548              delete pScene->mTextures[0];
   549              delete[] pScene->mTextures;
   550
   551              pScene->mTextures = nullptr;
   552              pScene->mNumTextures = 0;
   553          } else {
   554              clr.b = clr.a = clr.g = clr.r = 1.0f;
   555              aiString szString;
   556              ::memcpy(szString.data, AI_MAKE_EMBEDDED_TEXNAME(0), 3);
   557              szString.length = 2;
   558              pcHelper->AddProperty(&szString, AI_MATKEY_TEXTURE_DIFFUSE(0));
   559          }
   560      }
   561
   562      pcHelper->AddProperty<aiColor4D>(&clr, 1, AI_MATKEY_COLOR_DIFFUSE);
   563      pcHelper->AddProperty<aiColor4D>(&clr, 1, AI_MATKEY_COLOR_SPECULAR);
   564
   565      clr.r *= 0.05f;
   566      clr.g *= 0.05f;
   567      clr.b *= 0.05f;
   568      clr.a = 1.0f;
   569      pcHelper->AddProperty<aiColor4D>(&clr, 1, AI_MATKEY_COLOR_AMBIENT);
   570  }
