   721  void MDLImporter::ParseSkinLump_3DGS_MDL7(
   722          const unsigned char *szCurrent,
   723          const unsigned char **szCurrentOut,
   724          std::vector<aiMaterial *> &pcMats) {
   725      ai_assert(nullptr != szCurrent);
