   172  /** \struct Header_MDL7
   173   *  \brief Data structure for the MDL 7 main header
   174   */
   175  struct Header_MDL7 {
   176      //! magic number: "MDL7"
   177      char    ident[4];
   178
   179      //! Version number. Ignored
   180      int32_t version;
   181
   182      //! Number of bones in file
   183      uint32_t    bones_num;
   184
   185      //! Number of groups in file
   186      uint32_t    groups_num;
   187
   188      //! Size of data in the file
   189      uint32_t    data_size;
   190
   191      //! Ignored. Used to store entity specific information
   192      int32_t entlump_size;
   193
   194      //! Ignored. Used to store MED related data
   195      int32_t medlump_size;
   196
   197      //! Size of the Bone_MDL7 data structure used in the file
   198      uint16_t bone_stc_size;
   199
   200      //! Size of the Skin_MDL 7 data structure used in the file
   201      uint16_t skin_stc_size;
   202
   203      //! Size of a single color (e.g. in a material)
   204      uint16_t colorvalue_stc_size;
   205
   206      //! Size of the Material_MDL7 data structure used in the file
   207      uint16_t material_stc_size;
   208
   209      //! Size of a texture coordinate set in the file
   210      uint16_t skinpoint_stc_size;
   211
   212      //! Size of a triangle in the file
   213      uint16_t triangle_stc_size;
   214
   215      //! Size of a normal vertex in the file
   216      uint16_t mainvertex_stc_size;
   217
   218      //! Size of a per-frame animated vertex in the file
   219      //! (this is not supported)
   220      uint16_t framevertex_stc_size;
   221
   222      //! Size of a bone animation matrix
   223      uint16_t bonetrans_stc_size;
   224
   225      //! Size of the Frame_MDL7 data structure used in the file
   226      uint16_t frame_stc_size;
   227  } PACK_STRUCT;
