   230  // -------------------------------------------------------------------------------------
   411  /** \struct Skin_MDL7
   412   *  \brief Skin data structure #3 - used by MDL7 and HMP7
   413   */
   414  struct Skin_MDL7 {
   415      uint8_t         typ;
   416      int8_t          _unused_[3];
   417      int32_t         width;
   418      int32_t         height;
   419      char            texture_name[AI_MDL7_MAX_TEXNAMESIZE];
   420  } PACK_STRUCT;
