   422  // -------------------------------------------------------------------------------------
   423  /** \struct RGB565
   424   *  \brief Data structure for a RGB565 pixel in a texture
   425   */

820      const MDL::Header *const pcHeader = (const MDL::Header *)this->mBuffer;
   821      if (pcHeader->num_skins && this->pScene->mNumTextures) {
   822          const aiTexture *pcTex = this->pScene->mTextures[0];
   823
   824          // if the file is loaded in DDS format: get the size of the
   825          // texture from the header of the DDS file
   826          // skip three DWORDs and read first height, then the width
   827          unsigned int iWidth, iHeight;
   828          if (!pcTex->mHeight) {
   829              const uint32_t *piPtr = (uint32_t *)pcTex->pcData;
   830
   831              piPtr += 3;
   832              iHeight = (unsigned int)*piPtr++;
   833              iWidth = (unsigned int)*piPtr;
   834              if (!iHeight || !iWidth) {
   835                  ASSIMP_LOG_WARN("Either the width or the height of the "
   836                                  "embedded DDS texture is zero. Unable to compute final texture "
   837                                  "coordinates. The texture coordinates remain in their original "
   838                                  "0-x/0-y (x,y = texture size) range.");
   839                  iWidth = 1;
   840                  iHeight = 1;
   841              }
   842          } else {
   843              iWidth = pcTex->mWidth;
   844              iHeight = pcTex->mHeight;
   845          }
   846
   847          if (1 != iWidth || 1 != iHeight) {
   848              const float fWidth = (float)iWidth;
   849              const float fHeight = (float)iHeight;
   850              aiMesh *pcMesh = this->pScene->mMeshes[0];
   851              for (unsigned int i = 0; i < pcMesh->mNumVertices; ++i) {
   852                  pcMesh->mTextureCoords[0][i].x /= fWidth;
   853                  pcMesh->mTextureCoords[0][i].y /= fHeight;
   854                  pcMesh->mTextureCoords[0][i].y = 1.0f - pcMesh->mTextureCoords[0][i].y; // DX to OGL
   855              }
   856          }
   857      }
   858  }
