   861  // Validate the header of a MDL7 file
   862  void MDLImporter::ValidateHeader_3DGS_MDL7(const MDL::Header_MDL7 *pcHeader) {
   863      ai_assert(nullptr != pcHeader);
   864
   865      // There are some fixed sizes ...
   866      if (sizeof(MDL::ColorValue_MDL7) != pcHeader->colorvalue_stc_size) {
   867          throw DeadlyImportError(
   868                  "[3DGS MDL7] sizeof(MDL::ColorValue_MDL7) != pcHeader->colorvalue_stc_size");
   869      }
   870      if (sizeof(MDL::TexCoord_MDL7) != pcHeader->skinpoint_stc_size) {
   871          throw DeadlyImportError(
   872                  "[3DGS MDL7] sizeof(MDL::TexCoord_MDL7) != pcHeader->skinpoint_stc_size");
   873      }
   874      if (sizeof(MDL::Skin_MDL7) != pcHeader->skin_stc_size) {
   875          throw DeadlyImportError(
   876                  "sizeof(MDL::Skin_MDL7) != pcHeader->skin_stc_size");
   877      }
   878
   879      // if there are no groups ... how should we load such a file?
   880      if (!pcHeader->groups_num) {
   881          throw DeadlyImportError("[3DGS MDL7] No frames found");
   882      }
   883  }
