   885  // ------------------------------------------------------------------------------------------------
   886  // resolve bone animation matrices
   887  void MDLImporter::CalcAbsBoneMatrices_3DGS_MDL7(MDL::IntBone_MDL7 **apcOutBones) {
   888      const MDL::Header_MDL7 *pcHeader = (const MDL::Header_MDL7 *)this->mBuffer;
   889      const MDL::Bone_MDL7 *pcBones = (const MDL::Bone_MDL7 *)(pcHeader + 1);
   890      ai_assert(nullptr != apcOutBones);
   891
   892      // first find the bone that has NO parent, calculate the
   893      // animation matrix for it, then go on and search for the next parent
   894      // index (0) and so on until we can't find a new node.
   895      uint16_t iParent = 0xffff;
   896      uint32_t iIterations = 0;
   897      while (iIterations++ < pcHeader->bones_num) {
   898          for (uint32_t iBone = 0; iBone < pcHeader->bones_num; ++iBone) {
   899              BE_NCONST MDL::Bone_MDL7 *pcBone = _AI_MDL7_ACCESS_PTR(pcBones, iBone,
   900                      pcHeader->bone_stc_size, MDL::Bone_MDL7);
   901
   902              AI_SWAP2(pcBone->parent_index);
   903              AI_SWAP4(pcBone->x);
   904              AI_SWAP4(pcBone->y);
   905              AI_SWAP4(pcBone->z);
   906
   907              if (iParent == pcBone->parent_index) {
   908                  // MDL7 readme
   909                  ////////////////////////////////////////////////////////////////
   910                  /*
   911                  The animation matrix is then calculated the following way:
   912
   913                  vector3 bPos = <absolute bone position>
   914                  matrix44 laM;   // local animation matrix
   915                  sphrvector key_rotate = <bone rotation>
   916
   917                  matrix44 m1,m2;
   918                  create_trans_matrix(m1, -bPos.x, -bPos.y, -bPos.z);
   919                  create_trans_matrix(m2, -bPos.x, -bPos.y, -bPos.z);
   920
   921                  create_rotation_matrix(laM,key_rotate);
   922
   923                  laM = sm1 * laM;
   924                  laM = laM * sm2;
   925                  */
   926                  /////////////////////////////////////////////////////////////////
   927
   928                  MDL::IntBone_MDL7 *const pcOutBone = apcOutBones[iBone];
   929
   930                  // store the parent index of the bone
   931                  pcOutBone->iParent = pcBone->parent_index;
   932                  if (0xffff != iParent) {
   933                      const MDL::IntBone_MDL7 *pcParentBone = apcOutBones[iParent];
   934                      pcOutBone->mOffsetMatrix.a4 = -pcParentBone->vPosition.x;
   935                      pcOutBone->mOffsetMatrix.b4 = -pcParentBone->vPosition.y;
   936                      pcOutBone->mOffsetMatrix.c4 = -pcParentBone->vPosition.z;
   937                  }
   938                  pcOutBone->vPosition.x = pcBone->x;
   939                  pcOutBone->vPosition.y = pcBone->y;
   940                  pcOutBone->vPosition.z = pcBone->z;
   941                  pcOutBone->mOffsetMatrix.a4 -= pcBone->x;
   942                  pcOutBone->mOffsetMatrix.b4 -= pcBone->y;
   943                  pcOutBone->mOffsetMatrix.c4 -= pcBone->z;
   944
   945                  if (AI_MDL7_BONE_STRUCT_SIZE__NAME_IS_NOT_THERE == pcHeader->bone_stc_size) {
   946                      // no real name for our poor bone is specified :-(
   947                      pcOutBone->mName.length = ai_snprintf(pcOutBone->mName.data, MAXLEN,
   948                              "UnnamedBone_%i", iBone);
   949                  } else {
   950                      // Make sure we won't run over the buffer's end if there is no
   951                      // terminal 0 character (however the documentation says there
   952                      // should be one)
   953                      uint32_t iMaxLen = pcHeader->bone_stc_size - 16;
   954                      for (uint32_t qq = 0; qq < iMaxLen; ++qq) {
   955                          if (!pcBone->name[qq]) {
   956                              iMaxLen = qq;
   957                              break;
   958                          }
   959                      }
   960
   961                      // store the name of the bone
   962                      pcOutBone->mName.length = (size_t)iMaxLen;
   963                      ::memcpy(pcOutBone->mName.data, pcBone->name, pcOutBone->mName.length);
   964                      pcOutBone->mName.data[pcOutBone->mName.length] = '\0';
   965                  }
   966              }
   967          }
   968          ++iParent;
   969      }
   970  }
