   972  // ------------------------------------------------------------------------------------------------
   973  // read bones from a MDL7 file
   974  MDL::IntBone_MDL7 **MDLImporter::LoadBones_3DGS_MDL7() {
   975      const MDL::Header_MDL7 *pcHeader = (const MDL::Header_MDL7 *)this->mBuffer;
   976      if (pcHeader->bones_num) {
   977          // validate the size of the bone data structure in the file
   978          if (AI_MDL7_BONE_STRUCT_SIZE__NAME_IS_20_CHARS != pcHeader->bone_stc_size &&
   979                  AI_MDL7_BONE_STRUCT_SIZE__NAME_IS_32_CHARS != pcHeader->bone_stc_size &&
   980                  AI_MDL7_BONE_STRUCT_SIZE__NAME_IS_NOT_THERE != pcHeader->bone_stc_size) {
   981              ASSIMP_LOG_WARN("Unknown size of bone data structure");
   982              return nullptr;
   983          }
   984
   985          MDL::IntBone_MDL7 **apcBonesOut = new MDL::IntBone_MDL7 *[pcHeader->bones_num];
   986          for (uint32_t crank = 0; crank < pcHeader->bones_num; ++crank)
   987              apcBonesOut[crank] = new MDL::IntBone_MDL7();
   988
   989          // and calculate absolute bone offset matrices ...
   990          CalcAbsBoneMatrices_3DGS_MDL7(apcBonesOut);
   991          return apcBonesOut;
   992      }
   993      return nullptr;
   994  }
