   996  // ------------------------------------------------------------------------------------------------
   997  // read faces from a MDL7 file
   998  void MDLImporter::ReadFaces_3DGS_MDL7(const MDL::IntGroupInfo_MDL7 &groupInfo,
   999          MDL::IntGroupData_MDL7 &groupData) {
  1000      const MDL::Header_MDL7 *pcHeader = (const MDL::Header_MDL7 *)this->mBuffer;
  1001      MDL::Triangle_MDL7 *pcGroupTris = groupInfo.pcGroupTris;
  1002
  1003      // iterate through all triangles and build valid display lists
  1004      unsigned int iOutIndex = 0;
  1005      for (unsigned int iTriangle = 0; iTriangle < (unsigned int)groupInfo.pcGroup->numtris; ++iTriangle) {
  1006          AI_SWAP2(pcGroupTris->v_index[0]);
  1007          AI_SWAP2(pcGroupTris->v_index[1]);
  1008          AI_SWAP2(pcGroupTris->v_index[2]);
  1009
  1010          // iterate through all indices of the current triangle
  1011          for (unsigned int c = 0; c < 3; ++c, ++iOutIndex) {
  1012
  1013              // validate the vertex index
  1014              unsigned int iIndex = pcGroupTris->v_index[c];
  1015              if (iIndex > (unsigned int)groupInfo.pcGroup->numverts) {
  1016                  // (we might need to read this section a second time - to process frame vertices correctly)
  1017                  pcGroupTris->v_index[c] = (uint16_t)(iIndex = groupInfo.pcGroup->numverts - 1);
  1018                  ASSIMP_LOG_WARN("Index overflow in MDL7 vertex list");
  1019              }
  1020
  1021              // write the output face index
  1022              groupData.pcFaces[iTriangle].mIndices[2 - c] = iOutIndex;
  1023
  1024              aiVector3D &vPosition = groupData.vPositions[iOutIndex];
  1025              vPosition.x = _AI_MDL7_ACCESS_VERT(groupInfo.pcGroupVerts, iIndex, pcHeader->mainvertex_stc_size).x;
  1026              vPosition.y = _AI_MDL7_ACCESS_VERT(groupInfo.pcGroupVerts, iIndex, pcHeader->mainvertex_stc_size).y;
  1027              vPosition.z = _AI_MDL7_ACCESS_VERT(groupInfo.pcGroupVerts, iIndex, pcHeader->mainvertex_stc_size).z;
  1028
  1029              // if we have bones, save the index
  1030              if (!groupData.aiBones.empty()) {
  1031                  groupData.aiBones[iOutIndex] = _AI_MDL7_ACCESS_VERT(groupInfo.pcGroupVerts,
  1032                          iIndex, pcHeader->mainvertex_stc_size)
  1033                                                         .vertindex;
  1034              }
  1035
  1036              // now read the normal vector
  1037              if (AI_MDL7_FRAMEVERTEX030305_STCSIZE <= pcHeader->mainvertex_stc_size) {
  1038                  // read the full normal vector
  1039                  aiVector3D &vNormal = groupData.vNormals[iOutIndex];
  1040                  vNormal.x = _AI_MDL7_ACCESS_VERT(groupInfo.pcGroupVerts, iIndex, pcHeader->mainvertex_stc_size).norm[0];
  1041                  AI_SWAP4(vNormal.x);
  1042                  vNormal.y = _AI_MDL7_ACCESS_VERT(groupInfo.pcGroupVerts, iIndex, pcHeader->mainvertex_stc_size).norm[1];
  1043                  AI_SWAP4(vNormal.y);
  1044                  vNormal.z = _AI_MDL7_ACCESS_VERT(groupInfo.pcGroupVerts, iIndex, pcHeader->mainvertex_stc_size).norm[2];
  1045                  AI_SWAP4(vNormal.z);
  1046              } else if (AI_MDL7_FRAMEVERTEX120503_STCSIZE <= pcHeader->mainvertex_stc_size) {
  1047                  // read the normal vector from Quake2's smart table
  1048                  aiVector3D &vNormal = groupData.vNormals[iOutIndex];
  1049                  MD2::LookupNormalIndex(_AI_MDL7_ACCESS_VERT(groupInfo.pcGroupVerts, iIndex,
  1050                                                 pcHeader->mainvertex_stc_size)
  1051                                                 .norm162index,
  1052                          vNormal);
  1053              }
  1054              // validate and process the first uv coordinate set
  1055              if (pcHeader->triangle_stc_size >= AI_MDL7_TRIANGLE_STD_SIZE_ONE_UV) {
  1056
  1057                  if (groupInfo.pcGroup->num_stpts) {
  1058                      AI_SWAP2(pcGroupTris->skinsets[0].st_index[0]);
  1059                      AI_SWAP2(pcGroupTris->skinsets[0].st_index[1]);
  1060                      AI_SWAP2(pcGroupTris->skinsets[0].st_index[2]);
  1061
  1062                      iIndex = pcGroupTris->skinsets[0].st_index[c];
  1063                      if (iIndex > (unsigned int)groupInfo.pcGroup->num_stpts) {
  1064                          iIndex = groupInfo.pcGroup->num_stpts - 1;
  1065                          ASSIMP_LOG_WARN("Index overflow in MDL7 UV coordinate list (#1)");
  1066                      }
  1067
  1068                      float u = groupInfo.pcGroupUVs[iIndex].u;
  1069                      float v = 1.0f - groupInfo.pcGroupUVs[iIndex].v; // DX to OGL
  1070
  1071                      groupData.vTextureCoords1[iOutIndex].x = u;
  1072                      groupData.vTextureCoords1[iOutIndex].y = v;
  1073                  }
  1074                  // assign the material index, but only if it is existing
  1075                  if (pcHeader->triangle_stc_size >= AI_MDL7_TRIANGLE_STD_SIZE_ONE_UV_WITH_MATINDEX) {
  1076                      AI_SWAP4(pcGroupTris->skinsets[0].material);
  1077                      groupData.pcFaces[iTriangle].iMatIndex[0] = pcGroupTris->skinsets[0].material;
  1078                  }
  1079              }
  1080              // validate and process the second uv coordinate set
  1081              if (pcHeader->triangle_stc_size >= AI_MDL7_TRIANGLE_STD_SIZE_TWO_UV) {
  1082
  1083                  if (groupInfo.pcGroup->num_stpts) {
  1084                      AI_SWAP2(pcGroupTris->skinsets[1].st_index[0]);
  1085                      AI_SWAP2(pcGroupTris->skinsets[1].st_index[1]);
  1086                      AI_SWAP2(pcGroupTris->skinsets[1].st_index[2]);
  1087                      AI_SWAP4(pcGroupTris->skinsets[1].material);
  1088
  1089                      iIndex = pcGroupTris->skinsets[1].st_index[c];
  1090                      if (iIndex > (unsigned int)groupInfo.pcGroup->num_stpts) {
  1091                          iIndex = groupInfo.pcGroup->num_stpts - 1;
  1092                          ASSIMP_LOG_WARN("Index overflow in MDL7 UV coordinate list (#2)");
  1093                      }
  1094
  1095                      float u = groupInfo.pcGroupUVs[iIndex].u;
  1096                      float v = 1.0f - groupInfo.pcGroupUVs[iIndex].v;
  1097
  1098                      groupData.vTextureCoords2[iOutIndex].x = u;
  1099                      groupData.vTextureCoords2[iOutIndex].y = v; // DX to OGL
  1100
  1101                      // check whether we do really need the second texture
  1102                      // coordinate set ... wastes memory and loading time
  1103                      if (0 != iIndex && (u != groupData.vTextureCoords1[iOutIndex].x ||
  1104                                                 v != groupData.vTextureCoords1[iOutIndex].y))
  1105                          groupData.bNeed2UV = true;
  1106
  1107                      // if the material differs, we need a second skin, too
  1108                      if (pcGroupTris->skinsets[1].material != pcGroupTris->skinsets[0].material)
  1109                          groupData.bNeed2UV = true;
  1110                  }
  1111                  // assign the material index
  1112                  groupData.pcFaces[iTriangle].iMatIndex[1] = pcGroupTris->skinsets[1].material;
  1113              }
  1114          }
  1115          // get the next triangle in the list
  1116          pcGroupTris = (MDL::Triangle_MDL7 *)((const char *)pcGroupTris + pcHeader->triangle_stc_size);
  1117      }
  1118  }
