  1120  // ------------------------------------------------------------------------------------------------
  1121  // handle frames in a MDL7 file
  1122  bool MDLImporter::ProcessFrames_3DGS_MDL7(const MDL::IntGroupInfo_MDL7 &groupInfo,
  1123          MDL::IntGroupData_MDL7 &groupData,
  1124          MDL::IntSharedData_MDL7 &shared,
  1125          const unsigned char *szCurrent,
  1126          const unsigned char **szCurrentOut) {
  1127      ai_assert(nullptr != szCurrent);
  1128      ai_assert(nullptr != szCurrentOut);
  1129
  1130      const MDL::Header_MDL7 *pcHeader = (const MDL::Header_MDL7 *)mBuffer;
  1131
  1132      // if we have no bones we can simply skip all frames,
  1133      // otherwise we'll need to process them.
  1134      // FIX: If we need another frame than the first we must apply frame vertex replacements ...
  1135      for (unsigned int iFrame = 0; iFrame < (unsigned int)groupInfo.pcGroup->numframes; ++iFrame) {
  1136          MDL::IntFrameInfo_MDL7 frame((BE_NCONST MDL::Frame_MDL7 *)szCurrent, iFrame);
  1137
  1138          AI_SWAP4(frame.pcFrame->vertices_count);
  1139          AI_SWAP4(frame.pcFrame->transmatrix_count);
  1140
  1141          const unsigned int iAdd = pcHeader->frame_stc_size +
  1142                                    frame.pcFrame->vertices_count * pcHeader->framevertex_stc_size +
  1143                                    frame.pcFrame->transmatrix_count * pcHeader->bonetrans_stc_size;
  1144
  1145          if (((const char *)szCurrent - (const char *)pcHeader) + iAdd > (unsigned int)pcHeader->data_size) {
  1146              ASSIMP_LOG_WARN("Index overflow in frame area. "
  1147                              "Ignoring all frames and all further mesh groups, too.");
  1148
  1149              // don't parse more groups if we can't even read one
  1150              // FIXME: sometimes this seems to occur even for valid files ...
  1151              *szCurrentOut = szCurrent;
  1152              return false;
  1153          }
  1154          // our output frame?
  1155          if (configFrameID == iFrame) {
  1156              BE_NCONST MDL::Vertex_MDL7 *pcFrameVertices = (BE_NCONST MDL::Vertex_MDL7 *)(szCurrent + pcHeader->frame_stc_size);
  1157
  1158              for (unsigned int qq = 0; qq < frame.pcFrame->vertices_count; ++qq) {
  1159                  // I assume this are simple replacements for normal vertices, the bone index serving
  1160                  // as the index of the vertex to be replaced.
  1161                  uint16_t iIndex = _AI_MDL7_ACCESS(pcFrameVertices, qq, pcHeader->framevertex_stc_size, MDL::Vertex_MDL7).vertindex;
  1162                  AI_SWAP2(iIndex);
  1163                  if (iIndex >= groupInfo.pcGroup->numverts) {
  1164                      ASSIMP_LOG_WARN("Invalid vertex index in frame vertex section");
  1165                      continue;
  1166                  }
  1167
  1168                  aiVector3D vPosition, vNormal;
  1169
  1170                  vPosition.x = _AI_MDL7_ACCESS_VERT(pcFrameVertices, qq, pcHeader->framevertex_stc_size).x;
  1171                  AI_SWAP4(vPosition.x);
  1172                  vPosition.y = _AI_MDL7_ACCESS_VERT(pcFrameVertices, qq, pcHeader->framevertex_stc_size).y;
  1173                  AI_SWAP4(vPosition.y);
  1174                  vPosition.z = _AI_MDL7_ACCESS_VERT(pcFrameVertices, qq, pcHeader->framevertex_stc_size).z;
  1175                  AI_SWAP4(vPosition.z);
  1176
  1177                  // now read the normal vector
  1178                  if (AI_MDL7_FRAMEVERTEX030305_STCSIZE <= pcHeader->mainvertex_stc_size) {
  1179                      // read the full normal vector
  1180                      vNormal.x = _AI_MDL7_ACCESS_VERT(pcFrameVertices, qq, pcHeader->framevertex_stc_size).norm[0];
  1181                      AI_SWAP4(vNormal.x);
  1182                      vNormal.y = _AI_MDL7_ACCESS_VERT(pcFrameVertices, qq, pcHeader->framevertex_stc_size).norm[1];
  1183                      AI_SWAP4(vNormal.y);
  1184                      vNormal.z = _AI_MDL7_ACCESS_VERT(pcFrameVertices, qq, pcHeader->framevertex_stc_size).norm[2];
  1185                      AI_SWAP4(vNormal.z);
  1186                  } else if (AI_MDL7_FRAMEVERTEX120503_STCSIZE <= pcHeader->mainvertex_stc_size) {
  1187                      // read the normal vector from Quake2's smart table
  1188                      MD2::LookupNormalIndex(_AI_MDL7_ACCESS_VERT(pcFrameVertices, qq,
  1189                                                     pcHeader->framevertex_stc_size)
  1190                                                     .norm162index,
  1191                              vNormal);
  1192                  }
  1193
  1194                  // FIXME: O(n^2) at the moment ...
  1195                  BE_NCONST MDL::Triangle_MDL7 *pcGroupTris = groupInfo.pcGroupTris;
  1196                  unsigned int iOutIndex = 0;
  1197                  for (unsigned int iTriangle = 0; iTriangle < (unsigned int)groupInfo.pcGroup->numtris; ++iTriangle) {
  1198                      // iterate through all indices of the current triangle
  1199                      for (unsigned int c = 0; c < 3; ++c, ++iOutIndex) {
  1200                          // replace the vertex with the new data
  1201                          const unsigned int iCurIndex = pcGroupTris->v_index[c];
  1202                          if (iCurIndex == iIndex) {
  1203                              groupData.vPositions[iOutIndex] = vPosition;
  1204                              groupData.vNormals[iOutIndex] = vNormal;
  1205                          }
  1206                      }
  1207                      // get the next triangle in the list
  1208                      pcGroupTris = (BE_NCONST MDL::Triangle_MDL7 *)((const char *)
  1209                                                                             pcGroupTris +
  1210                                                                     pcHeader->triangle_stc_size);
  1211                  }
  1212              }
  1213          }
  1214          // parse bone trafo matrix keys (only if there are bones ...)
  1215          if (shared.apcOutBones) {
  1216              ParseBoneTrafoKeys_3DGS_MDL7(groupInfo, frame, shared);
  1217          }
  1218          szCurrent += iAdd;
  1219      }
  1220      *szCurrentOut = szCurrent;

1220      *szCurrentOut = szCurrent;
  1221      return true;
  1222  }
