  1224  // ------------------------------------------------------------------------------------------------
  1225  // Sort faces by material, handle multiple UVs correctly
  1226  void MDLImporter::SortByMaterials_3DGS_MDL7(
  1227          const MDL::IntGroupInfo_MDL7 &groupInfo,
  1228          MDL::IntGroupData_MDL7 &groupData,
  1229          MDL::IntSplitGroupData_MDL7 &splitGroupData) {
  1230      const unsigned int iNumMaterials = (unsigned int)splitGroupData.shared.pcMats.size();
  1231      if (!groupData.bNeed2UV) {
  1232          // if we don't need a second set of texture coordinates there is no reason to keep it in memory ...
  1233          groupData.vTextureCoords2.clear();
  1234
  1235          // allocate the array
  1236          splitGroupData.aiSplit = new std::vector<unsigned int> *[iNumMaterials];
  1237
  1238          for (unsigned int m = 0; m < iNumMaterials; ++m)
  1239              splitGroupData.aiSplit[m] = new std::vector<unsigned int>();
  1240
  1241          // iterate through all faces and sort by material
  1242          for (unsigned int iFace = 0; iFace < (unsigned int)groupInfo.pcGroup->numtris; ++iFace) {
  1243              // check range
  1244              if (groupData.pcFaces[iFace].iMatIndex[0] >= iNumMaterials) {
  1245                  // use the last material instead
  1246                  splitGroupData.aiSplit[iNumMaterials - 1]->push_back(iFace);
  1247
  1248                  // sometimes MED writes -1, but normally only if there is only
  1249                  // one skin assigned. No warning in this case
  1250                  if (0xFFFFFFFF != groupData.pcFaces[iFace].iMatIndex[0])
  1251                      ASSIMP_LOG_WARN("Index overflow in MDL7 material list [#0]");
  1252              } else
  1253                  splitGroupData.aiSplit[groupData.pcFaces[iFace].iMatIndex[0]]->push_back(iFace);
  1254          }
  1255      } else {
  1256          // we need to build combined materials for each combination of
  1257          std::vector<MDL::IntMaterial_MDL7> avMats;
  1258          avMats.reserve(iNumMaterials * 2);
  1259
  1260          // fixme: why on the heap?
  1261          std::vector<std::vector<unsigned int> *> aiTempSplit(iNumMaterials * 2);
  1262          for (unsigned int m = 0; m < iNumMaterials; ++m)
  1263              aiTempSplit[m] = new std::vector<unsigned int>();
  1264
  1265          // iterate through all faces and sort by material
  1266          for (unsigned int iFace = 0; iFace < (unsigned int)groupInfo.pcGroup->numtris; ++iFace) {
  1267              // check range
  1268              unsigned int iMatIndex = groupData.pcFaces[iFace].iMatIndex[0];
  1269              if (iMatIndex >= iNumMaterials) {
  1270                  // sometimes MED writes -1, but normally only if there is only
  1271                  // one skin assigned. No warning in this case
  1272                  if (UINT_MAX != iMatIndex)
  1273                      ASSIMP_LOG_WARN("Index overflow in MDL7 material list [#1]");
  1274                  iMatIndex = iNumMaterials - 1;
  1275              }
  1276              unsigned int iMatIndex2 = groupData.pcFaces[iFace].iMatIndex[1];
  1277
  1278              unsigned int iNum = iMatIndex;
  1279              if (UINT_MAX != iMatIndex2 && iMatIndex != iMatIndex2) {
  1280                  if (iMatIndex2 >= iNumMaterials) {
  1281                      // sometimes MED writes -1, but normally only if there is only
  1282                      // one skin assigned. No warning in this case
  1283                      ASSIMP_LOG_WARN("Index overflow in MDL7 material list [#2]");
  1284                      iMatIndex2 = iNumMaterials - 1;
  1285                  }
  1286
  1287                  // do a slow search in the list ...
  1288                  iNum = 0;
  1289                  bool bFound = false;
  1290                  for (std::vector<MDL::IntMaterial_MDL7>::iterator i = avMats.begin(); i != avMats.end(); ++i, ++iNum) {
  1291                      if ((*i).iOldMatIndices[0] == iMatIndex && (*i).iOldMatIndices[1] == iMatIndex2) {
  1292                          // reuse this material
  1293                          bFound = true;
  1294                          break;
  1295                      }
  1296                  }
  1297                  if (!bFound) {
  1298                      //  build a new material ...
  1299                      MDL::IntMaterial_MDL7 sHelper;
  1300                      sHelper.pcMat = new aiMaterial();
  1301                      sHelper.iOldMatIndices[0] = iMatIndex;
  1302                      sHelper.iOldMatIndices[1] = iMatIndex2;
  1303                      JoinSkins_3DGS_MDL7(splitGroupData.shared.pcMats[iMatIndex],
  1304                              splitGroupData.shared.pcMats[iMatIndex2], sHelper.pcMat);
  1305
  1306                      // and add it to the list
  1307                      avMats.push_back(sHelper);
  1308                      iNum = (unsigned int)avMats.size() - 1;
  1309                  }
  1310                  // adjust the size of the file array
  1311                  if (iNum == aiTempSplit.size()) {
  1312                      aiTempSplit.push_back(new std::vector<unsigned int>());
  1313                  }
  1314              }
  1315              aiTempSplit[iNum]->push_back(iFace);
  1316          }
  1317
  1318          // now add the newly created materials to the old list
  1319          if (0 == groupInfo.iIndex) {
  1320              splitGroupData.shared.pcMats.resize(avMats.size());
  1321              for (unsigned int o = 0; o < avMats.size(); ++o)
  1322                  splitGroupData.shared.pcMats[o] = avMats[o].pcMat;
  1323          } else {
  1324              // This might result in redundant materials ...
  1325              splitGroupData.shared.pcMats.resize(iNumMaterials + avMats.size());
  1326              for (unsigned int o = iNumMaterials; o < avMats.size(); ++o)
  1327                  splitGroupData.shared.pcMats[o] = avMats[o].pcMat;
  1328          }
  1329
  1330          // and build the final face-to-material array
  1331          splitGroupData.aiSplit = new std::vector<unsigned int> *[aiTempSplit.size()];
  1332          for (unsigned int m = 0; m < iNumMaterials; ++m)
  1333              splitGroupData.aiSplit[m] = aiTempSplit[m];
  1334      }
  1335  }
