   494          return AI_SUCCESS;
   495      }
   496
   497      // resize the array ... double the storage allocated
   498      if (mNumProperties == mNumAllocated) {
   499          const unsigned int iOld = mNumAllocated;
   500          mNumAllocated *= 2;
   501
   502          aiMaterialProperty **ppTemp;
   503          try {
   504              ppTemp = new aiMaterialProperty *[mNumAllocated];
   505          } catch (std::bad_alloc &) {
   506              delete pcNew;
   507              return AI_OUTOFMEMORY;
   508          }
   509
   510          // just copy all items over; then replace the old array
   511          memcpy(ppTemp, mProperties, iOld * sizeof(void *));
